23	func ValidateAlert(a models.Alert) error {
24		if a.Channel == "" {
25			return errors.New("alert: empty channel")
26		}
27		if a.Summary == "" {
28			return errors.New("alert: empty summary")
29		}
30		if len(a.Summary) > 512 {
31			return fmt.Errorf("alert: summary of %d bytes is too long", len(a.Summary))
32		}
