104	
105	// Repository stores one JSON file per snapshot under a directory.
106	type Repository struct {
107		dir string
108	}
109	
110	// NewRepository opens the store under dir, creating the directory if needed.
111	func NewRepository(dir string) (Repository, error) {
112		if dir == "" {
113			return Repository{}, errors.New("snapshot repository: empty dir")
114		}
115		if err := os.MkdirAll(dir, 0o750); err != nil {
116			return Repository{}, fmt.Errorf("snapshot repository: mkdir %s: %w", dir, err)
117		}
118		return Repository{dir: dir}, nil
119	}
120	
121	// Put writes the snapshot, replacing any earlier record with the same id.
122	func (r Repository) Put(sn models.Snapshot) error {
123		data, err := json.Marshal(sn)
124		if err != nil {
125			return fmt.Errorf("snapshot repository: encode %s: %w", sn.ID, err)
126		}
127		if err := os.WriteFile(r.path(sn.ID), data, 0o600); err != nil {
128			return fmt.Errorf("snapshot repository: write %s: %w", sn.ID, err)
129		}
130		return nil
131	}
132	
133	// Delete removes the snapshot with the given id. Deleting an unknown id is
134	// not an error: a prune that races a manual cleanup should still succeed.
135	func (r Repository) Delete(id string) error {
136		if err := os.Remove(r.path(id)); err != nil && !errors.Is(err, os.ErrNotExist) {
137			return fmt.Errorf("snapshot repository: delete %s: %w", id, err)
138		}
139		return nil
140	}
141	
142	// List returns the snapshots of deviceID, oldest first.
143	func (r Repository) List(deviceID string) ([]models.Snapshot, error) {
144		entries, err := os.ReadDir(r.dir)
145		if err != nil {
146			return nil, fmt.Errorf("snapshot repository: read %s: %w", r.dir, err)
147		}
148		var out []models.Snapshot
149		for _, entry := range entries {
150			if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".json") {
151				continue
152			}
153			sn, err := r.read(entry.Name())
154			if err != nil {
155				return nil, err
156			}
157			if sn.DeviceID == deviceID {
158				out = append(out, sn)
159			}
160		}
161		slices.SortFunc(out, func(a, b models.Snapshot) int { return a.CreatedAt.Compare(b.CreatedAt) })
162		return out, nil
163	}
164	
165	func (r Repository) read(name string) (models.Snapshot, error) {
166		data, err := os.ReadFile(filepath.Join(r.dir, name))
167		if err != nil {
168			return models.Snapshot{}, fmt.Errorf("snapshot repository: read %s: %w", name, err)
169		}
170		var sn models.Snapshot
171		if err := json.Unmarshal(data, &sn); err != nil {
172			return models.Snapshot{}, fmt.Errorf("snapshot repository: decode %s: %w", name, err)
173		}
174		return sn, nil
175	}
176	
177	func (r Repository) path(id string) string {
178		return filepath.Join(r.dir, url.PathEscape(id)+".json")
179	}

