 56	
 57	import (
 58		"encoding/json"
 59		"io"
 60		"net/http"
 61	
 62		"example.com/go-mini/internal/services"
 63	)
 64	
 65	// maxHeartbeatBytes bounds a heartbeat line; the longest legitimate line is
 66	// well under a kilobyte.
 67	const maxHeartbeatBytes = 4096
 68	
 69	type heartbeatResponse struct {
 70		ID      string   `json:"id"`
 71		Score   int      `json:"score"`
 72		Changed bool     `json:"changed"`
 73		Tags    []string `json:"tags"`
 74	}
 75	
 76	// Heartbeat returns the heartbeat handler. The body is one raw heartbeat
 77	// line, the tenant comes from the X-Tenant header and ?force=1 forces the
 78	// reported status through.
 79	func Heartbeat(svc *services.DeviceService) http.HandlerFunc {
 80		return func(w http.ResponseWriter, r *http.Request) {
 81			raw, err := io.ReadAll(http.MaxBytesReader(w, r.Body, maxHeartbeatBytes))
 82			if err != nil {
 83				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "unreadable body"})
 84				return
 85			}
 86			tenant := r.Header.Get("X-Tenant")
 87			if tenant == "" {
 88				tenant = "default"
 89			}
 90			force := r.URL.Query().Get("force") == "1"
 91	
 92			id, score, changed, tags, err := svc.ProcessHeartbeat(string(raw), tenant, force)
 93			if err != nil {
 94				writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
 95				return
 96			}
 97			if tags == nil {
 98				tags = []string{}
 99			}
100			writeJSON(w, http.StatusOK, heartbeatResponse{ID: id, Score: score, Changed: changed, Tags: tags})
101		}
102	}
103	
104	func writeJSON(w http.ResponseWriter, status int, v any) {
105		w.Header().Set("Content-Type", "application/json")
106		w.WriteHeader(status)
107		_ = json.NewEncoder(w).Encode(v)
108	}

