36	func (p *Placer) pickReplicas(nodes []Node, zone string) (Node, Node, error) {
37		var primary, secondary Node
38		primaryFound, secondaryFound := false, false
39		for _, n := range nodes {
40			if n.Zone == "" || n.Capacity <= 0 {
41				continue
42			}
43			if n.Zone == zone {
44				if primaryFound {
45					continue
46				}
47				primary, primaryFound = n, true
48				continue
49			}
50			if secondaryFound {
51				continue
52			}
53			secondary, secondaryFound = n, true
54		}
55		if !primaryFound || !secondaryFound {
56			return Node{}, Node{}, fmt.Errorf("no placement for zone %q", zone)
57		}
58		return primary, secondary, nil
59	}

