 15	
 16	// FileRepo is a repo backed by a file.
 17	type FileRepo struct {
 18		path string
 19		mu   sync.Mutex
 20	}
 21	
 22	// NewFileRepo creates a new FileRepo.
 23	func NewFileRepo(path string) (*FileRepo, error) {
 24		if path == "" {
 25			return nil, errors.New("file repo: empty path")
 26		}
 27		return &FileRepo{path: path}, nil
 28	}
 29	
 30	// Get gets a device.
 31	func (r *FileRepo) Get(ctx context.Context, tenant, id string) (models.Device, error) {
 32		if err := ctx.Err(); err != nil {
 33			return models.Device{}, fmt.Errorf("file repo: get: %w", err)
 34		}
 35		r.mu.Lock()
 36		defer r.mu.Unlock()
 37		devices, err := r.load()
 38		if err != nil {
 39			return models.Device{}, err
 40		}
 41		d, ok := devices[key(tenant, id)]
 42		if !ok {
 43			return models.Device{}, ErrNotFound
 44		}
 45		return d, nil
 46	}
 47	
 48	// Save saves a device.
 49	func (r *FileRepo) Save(ctx context.Context, d models.Device) error {
 50		if err := ctx.Err(); err != nil {
 51			return fmt.Errorf("file repo: save: %w", err)
 52		}
 53		r.mu.Lock()
 54		defer r.mu.Unlock()
 55		devices, err := r.load()
 56		if err != nil {
 57			return err
 58		}
 59		devices[key(d.Tenant, d.ID)] = d
 60		return r.store(devices)
 61	}
 62	
 63	// List lists all devices.
 64	func (r *FileRepo) List(ctx context.Context) ([]models.Device, error) {
 65		if err := ctx.Err(); err != nil {
 66			return nil, fmt.Errorf("file repo: list: %w", err)
 67		}
 68		r.mu.Lock()
 69		defer r.mu.Unlock()
 70		devices, err := r.load()
 71		if err != nil {
 72			return nil, err
 73		}
 74		return sorted(devices), nil
 75	}
 76	
 77	func (r *FileRepo) load() (map[string]models.Device, error) {
 78		data, err := os.ReadFile(r.path)
 79		if errors.Is(err, os.ErrNotExist) {
 80			return map[string]models.Device{}, nil
 81		}
 82		if err != nil {
 83			return nil, fmt.Errorf("file repo: read %s: %w", r.path, err)
 84		}
 85		devices := map[string]models.Device{}
 86		if err := json.Unmarshal(data, &devices); err != nil {
 87			return nil, fmt.Errorf("file repo: decode %s: %w", r.path, err)
 88		}
 89		return devices, nil
 90	}
 91	
 92	func (r *FileRepo) store(devices map[string]models.Device) error {
 93		data, err := json.MarshalIndent(devices, "", "  ")
 94		if err != nil {
 95			return fmt.Errorf("file repo: encode: %w", err)
 96		}
 97		if err := os.WriteFile(r.path, data, 0o600); err != nil {
 98			return fmt.Errorf("file repo: write %s: %w", r.path, err)
 99		}
100		return nil
101	}
102	
103	func sorted(devices map[string]models.Device) []models.Device {
104		out := make([]models.Device, 0, len(devices))
105		for _, d := range devices {
106			out = append(out, d)
107		}
108		slices.SortFunc(out, func(a, b models.Device) int {
109			return strings.Compare(key(a.Tenant, a.ID), key(b.Tenant, b.ID))
110		})
111		return out
112	}

