 2	package utils //nolint:revive // TODO
 3	
 4	import (
 5		"strings"
 6		"unicode"
 7	)
 8	
 9	// Truncate truncates s to at most n runes.
10	func Truncate(s string, n int) string {
11		if n <= 0 {
12			return ""
13		}
14		r := []rune(s)
15		if len(r) <= n {
16			return s
17		}
18		return string(r[:n])
19	}
20	
21	// Slugify lowercases s and replaces runs of non-alphanumerics with a dash.
22	func Slugify(s string) string {
23		var b strings.Builder
24		dash := false
25		for _, c := range strings.ToLower(s) {
26			if unicode.IsLetter(c) || unicode.IsDigit(c) {
27				b.WriteRune(c)
28				dash = false
29				continue
30			}
31			if !dash && b.Len() > 0 {
32				b.WriteByte('-')
33				dash = true
34			}
35		}
36		return strings.TrimSuffix(b.String(), "-")
37	}
38	
39	// Contains reports whether xs contains x.
40	func Contains(xs []string, x string) bool {
41		for _, v := range xs {
42			if v == x {
43				return true
44			}
45		}
46		return false
47	}

