1	package report
2	
3	import "slices"
4	
5	// Device is a device known to the catalog.
6	type Device struct {
7		Name  string
8		Model string
9	}
10	
11	// Event returns the catalog event for the device.
12	func (d Device) Event() Event {
13		return Event{Kind: "catalog", Subject: d.Name + "/" + d.Model}
14	}
15	
16	// Catalog is a catalog of devices.
17	type Catalog struct {
18		devices []Device
19	}
20	
21	// NewCatalog creates a new Catalog holding its own copy of devices.
22	func NewCatalog(devices []Device) *Catalog {
23		return &Catalog{devices: slices.Clone(devices)}
24	}
25	
26	// Find finds the device by name.
27	func (c *Catalog) Find(name string) *Device {
28		for i := range c.devices {
29			if c.devices[i].Name == name {
30				return &c.devices[i]
31			}
32		}
33		return nil
34	}
