64	// Raise raises the alert that matches the device's status.
65	func (s *AlertService) Raise(d models.Device) error {
66		s.recieved++ //nolint:misspell // TODO
67		s.lastAt = time.Now()
68		var a models.Alert
69		//nolint:goconst // TODO
70		switch d.Status {
71		case "READY":
72			return nil
73		case "DEGRADED":
74			a = models.Alert{Channel: "slack", Recipient: "#fleet", Summary: "device " + d.ID + " is degraded"}
75		case "DOWN":
