81	// syncOne syncs a single device and reports whether it was in scope.
82	func (s *SyncService) syncOne(d models.Device) (bool, error) {
83		if !s.inRegion(d) {
84			return false, nil
85		}
86		if s.dryRun {
87			log.Printf("sync: would save %s/%s", d.Tenant, d.ID)
88			return true, nil
89		}
90		if err := s.saveWithRetry(d); err != nil {
91			return false, err
92		}
93		return true, nil
94	}
95	
96	// inRegion reports whether the device belongs to the region this service
97	// is responsible for. An unset region means every device.
98	func (s *SyncService) inRegion(d models.Device) bool {
99		region := s.region
100		if region == "" {
101			region = os.Getenv("REGION")
102		}
103		if region == "" {
104			return true
105		}
106		want := "region:" + region
107		for _, t := range d.Tags {
108			if t == want {
109				return true
110			}
111		}
112		return false
113	}
114	
115	func (s *SyncService) saveWithRetry(d models.Device) error {
116		var err error
117		for attempt := 0; attempt <= s.retries; attempt++ {
118			err = s.repo.Save(context.TODO(), d)
119			if err == nil {
120				return nil
121			}
122			time.Sleep(time.Duration(attempt+1) * 100 * time.Millisecond)
123		}
124		_ = s.notifier.Send("ops", "sync failed for "+d.ID)
125		return fmt.Errorf("sync: save %s: %w", d.ID, err)
126	}
