8	
9	// Node is a storage node.
10	type Node struct {
11		ID       string
12		Zone     string
13		Capacity int
14	}
15	
16	// Placer is a placer.
17	type Placer struct {
18		logger *log.Logger
19	}
20	
21	// NewPlacer creates a new Placer.
22	func NewPlacer() *Placer {
23		return &Placer{logger: log.Default()}
24	}
25	
26	// Pick picks a primary node in zone and a secondary node outside it.
27	func (p *Placer) Pick(nodes []Node, zone string) (Node, Node, error) {
28		primary, secondary, err := p.pickReplicas(nodes, zone)
29		if err != nil {
30			p.logger.Printf("placement: %v", err)
31			return Node{}, Node{}, err
32		}
33		return primary, secondary, nil
34	}
35	
36	func (p *Placer) pickReplicas(nodes []Node, zone string) (Node, Node, error) {
37		var primary, secondary Node
38		primaryFound, secondaryFound := false, false
39		for _, n := range nodes {
40			if n.Zone == "" || n.Capacity <= 0 {
41				continue
42			}
43			if n.Zone == zone {
44				if primaryFound {
45					continue
46				}
47				primary, primaryFound = n, true
48				continue
49			}
50			if secondaryFound {
51				continue
52			}
