73	// DeviceService is a service for devices.
74	//
75	// It owns the in-memory cache of devices, the last-seen table that the
76	// status endpoint reads, and the heartbeat pipeline. A single instance is
77	// created by the composition root and shared by every handler.
78	type DeviceService struct {
79		repo     repository.DeviceRepository
80		notifier *Notifier
81		audit    *AuditLog
82		mu       sync.Mutex
83		cache    map[string]models.Device
84		lastSeen map[string]time.Time
85		started  time.Time
86		hits     int
87		misses   int
88		retries  int
89	}
90	
91	// NewDeviceService creates a new DeviceService.
92	//
93	// The notifier and the audit log may be nil; both degrade to no-ops.
94	func NewDeviceService(repo repository.DeviceRepository, notifier *Notifier, audit *AuditLog) *DeviceService {
95		s := &DeviceService{
96			repo:     repo,
97			notifier: notifier,
98			audit:    audit,
99			cache:    map[string]models.Device{},
100			lastSeen: map[string]time.Time{},
101			started:  time.Now(),
102		}
103		go s.flushLoop()
104		return s
105	}
