1	// Package report writes fleet events to an operator-visible sink.
2	package report
3	
4	import (
5		"fmt"
6		"io"
7		"time"
8	)
9	
10	// Reporter is a reporter.
11	type Reporter struct {
12		Sink  *Sink            // exported, might be nil — "optional"
13		Clock func() time.Time // nil means "use time.Now"
14	
15		flushEvery time.Duration
16	}
17	
18	// Options are the reporter options.
19	type Options struct {
20		FlushEvery time.Duration
21	}
22	
23	// Event is a reported event.
24	type Event struct {
25		Kind    string
26		Subject string
27	
28		at time.Time
29	}
30	
31	// At returns the event stamped with t.
32	func (e Event) At(t time.Time) Event {
33		e.at = t
34		return e
35	}
36	
37	// Time returns when the event was recorded.
38	func (e Event) Time() time.Time {
39		return e.at
40	}
41	
42	// Sink is where events are written.
43	type Sink struct {
44		w io.Writer
45	}
46	
47	// NewSink creates a new Sink.
48	func NewSink(w io.Writer) *Sink {
49		return &Sink{w: w}
50	}
51	
52	// Write writes the event.
53	func (s *Sink) Write(ev Event) {
54		_, _ = fmt.Fprintf(s.w, "%s %s %s\n", ev.at.UTC().Format(time.RFC3339), ev.Kind, ev.Subject)
55	}
56	
57	// NewReporter creates a new Reporter. Callers pass nil for "no options" and
58	// "default clock".
59	func NewReporter(sink *Sink, clock func() time.Time, opts *Options) *Reporter {
60		if opts == nil {
61			opts = &Options{}
62		}
63		if clock == nil {
64			clock = time.Now
65		}
66		return &Reporter{Sink: sink, Clock: clock, flushEvery: opts.FlushEvery}
67	}
68	
69	// Record records the event.
70	func (r *Reporter) Record(ev Event) {
71		if r.Sink == nil { // forget this once → panic
72			return
73		}
74		if r.Clock == nil {
75			r.Clock = time.Now
76		}
77		r.Sink.Write(ev.At(r.Clock()))
78	}
79	
80	// FlushEvery returns how often the sink is flushed.
81	func (r *Reporter) FlushEvery() time.Duration {
82		return r.flushEvery
83	}
84

