12	
13	// Schedule is a schedule.
14	type Schedule struct {
15		days []Weekday
16	}
17	
18	// NewSchedule creates a new Schedule.
19	func NewSchedule(days []Weekday) (Schedule, error) {
20		if len(days) == 0 {
21			return Schedule{}, errors.New("schedule: no days")
22		}
23		for _, d := range days {
24			if d < time.Sunday || d > time.Saturday {
25				return Schedule{}, fmt.Errorf("schedule: bad weekday %d", d)
26			}
27		}
28		return Schedule{days: days}, nil
29	}
