1	// Package pool runs jobs on a fixed set of worker goroutines.
2	package pool
3	
4	import (
5		"log"
6	
7		"example.com/go-mini/internal/env"
8	)
9	
10	// Job is a unit of work handed to a worker.
11	type Job struct {
12		ID  string
13		Run func()
14	}
15	
16	// Start starts the workers.
17	func Start(jobs <-chan Job) {
18		for i := 0; i < env.Config.NumWorkers; i++ {
19			go worker(jobs)
20		}
21	}
22	
23	func worker(jobs <-chan Job) {
24		for j := range jobs {
25			if j.Run != nil {
26				j.Run()
27			}
28			log.Printf("pool: job %s done", j.ID)
29		}
30	}
